recipes.code:
{
  "inputs": [
    {
      "id": "swt3-api-key",
      "type": "promptString",
      "description": "SWT3 API key (starts with axm_). Omit for zero-config demo mode.",
      "password": true
    },
    {
      "id": "swt3-signing-key",
      "type": "promptString",
      "description": "HMAC-SHA256 signing key for non-repudiation",
      "password": true
    }
  ],
  "servers": {
    "swt3-witness": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@tenova/swt3-mcp@0.6.1"
      ],
      "env": {
        "SWT3_API_KEY": "${input:swt3-api-key}",
        "SWT3_TENANT_ID": "<swt3-tenant-id>",
        "SWT3_CONFIG_FILE": "<swt3-config-file>",
        "SWT3_CLEARING_LEVEL": "<swt3-clearing-level>",
        "SWT3_AGENT_ID": "<swt3-agent-id>",
        "SWT3_SIGNING_KEY": "${input:swt3-signing-key}"
      }
    }
  }
}
